def collect_tags(posts, seen=None):
    if seen is None:
        seen = []
    for post in posts:
        if not post:
            continue
        for tag in post.get("tags", []):
            if not tag:
                continue
            tag_lc = tag.lower()
            if tag_lc not in seen:
                seen.append(tag_lc)
    return seen

def is_eligible(age, income, student, veteran, state, score):
    """Determine eligibility based on age, income, student status, veteran status, state, and score.

    The logic mirrors the original implementation but is broken into small, named helpers
    and uses early returns to keep the cyclomatic complexity low.
    """
    def _basic_criteria():
        # (age >= 18 and income < 40000) or (student and age < 26) or veteran
        return (age >= 18 and income < 40000) or (student and age < 26) or veteran

    def _state_criteria():
        # state == "NY" or state == "NJ" or (state == "CT" and score > 600)
        return state in {"NY", "NJ"} or (state == "CT" and score > 600)

    def _score_income_criteria():
        # (score > 700 and income < 60000) or (veteran and score > 550)
        return (score > 700 and income < 60000) or (veteran and score > 550)

    def _senior_criteria():
        # (age > 65 and income < 30000) or age > 70
        return (age > 65 and income < 30000) or (age > 70)

    # First eligibility block
    if _basic_criteria():
        if _state_criteria() or _score_income_criteria():
            return True

    # Senior eligibility block
    if _senior_criteria():
        return (score > 500) or veteran

    return False

def grade_summary(math=None, science=None, english=None):
    """Return a dict mapping each provided subject to its letter grade."""
    def _letter_grade(scores):
        if not scores:
            return None
        avg = sum(scores) / len(scores)
        for threshold, grade in ((90, "A"), (80, "B"), (70, "C")):
            if avg >= threshold:
                return grade
        return "F"

    out = {}
    for name, scores in (("math", math), ("science", science), ("english", english)):
        if scores:
            out[name] = _letter_grade(scores)
    return out

def to_csv(rows, columns):
    def _format(value):
        if value is None:
            return ""
        if isinstance(value, str):
            return f'"{value}"' if ',' in value else value
        return str(value)
    lines = [",".join(columns)]
    for row in rows:
        values = [_format(row.get(col)) for col in columns]
        lines.append(",".join(values))
    return "\n".join(lines) + "\n"
